// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 depositAmount) public {
        bound(depositAmount, 1 ether, 1 ether);

        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        address sender = address(0x1234);
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: depositAmount}("");

        assertTrue(
            (address(c).balance == balanceBefore + depositAmount) &&
            (c.depositsCount() == depositsBefore + 1)
        );
    }
}
